mapper.insert:
insert into tb_second_hand_message(
    id, product_id, order_id, sender_id, receiver_id, content, deleted, create_time
) values(
    null, #{productId}, #{orderId}, #{senderId}, #{receiverId}, #{content}, #{deleted}, #{createTime}
)

mapper.select:
select count(1)
from (
    select buyer_id as user_id
    from tb_second_hand_bargain
    where deleted = 0
      and product_id = #{productId}
      and seller_id = #{sellerId}
      and buyer_id = #{userId}
    union
    select buyer_id as user_id
    from tb_second_hand_order
    where deleted = 0
      and product_id = #{productId}
      and seller_id = #{sellerId}
      and buyer_id = #{userId}
    union
    select case when sender_id = #{sellerId} then receiver_id else sender_id end as user_id
    from tb_second_hand_message
    where deleted = 0
      and product_id = #{productId}
      and (
        (sender_id = #{sellerId} and receiver_id = #{userId})
        or (sender_id = #{userId} and receiver_id = #{sellerId})
      )
) participant

select from tb_second_hand_message m left join tb_user sender on m.sender_id = sender.id left join tb_user receiver on m.receiver_id = receiver.id
m.deleted = 0 and m.product_id = #{productId}
order by m.create_time desc
